--
-- Table structure for table `consultations`
--

DROP TABLE IF EXISTS `consultations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `consultations` (
  `booking_id` bigint NOT NULL AUTO_INCREMENT,
  `txn_id` varchar(100) NOT NULL,
  `patient_name` varchar(100) NOT NULL,
  `age` float NOT NULL,
  `gender` varchar(10) NOT NULL,
  `phone` varchar(20) NOT NULL,
  `appointment_date` varchar(20) NOT NULL,
  `appointment_time_slot` varchar(20) NOT NULL,
  `chief_complaint` varchar(500) DEFAULT NULL,
  `blood_reports` varchar(500) DEFAULT NULL,
  `xray_reports` varchar(500) DEFAULT NULL,
  `scan_reports` varchar(500) DEFAULT NULL,
  `consultation_fees` varchar(10) NOT NULL,
  `doctor_name` varchar(100) NOT NULL,
  `booked_by` varchar(100) NOT NULL,
  `status` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'Scheduled',
  `notify` int NOT NULL DEFAULT '0',
  `date_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`booking_id`,`txn_id`)
) ENGINE=MyISAM AUTO_INCREMENT=643 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

