DROP TABLE IF EXISTS `doctor_patients`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `doctor_patients` (
  `doctor_name` varchar(100) DEFAULT NULL,
  `doctor_id` varchar(100) NOT NULL,
  `qualification` varchar(255) DEFAULT NULL,
  `mci_license_number` varchar(50) DEFAULT NULL,
  `doctor_phone` varchar(20) DEFAULT NULL,
  `patient_name` varchar(100) DEFAULT NULL,
  `patient_id` varchar(100) DEFAULT NULL,
  `patient_age` varchar(20) DEFAULT NULL,
  `patient_gender` varchar(20) DEFAULT NULL,
  `chief_complaints` varchar(1000) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `observations` varchar(1000) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `investigations` varchar(1000) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `advices` varchar(1000) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `med_id` bigint NOT NULL AUTO_INCREMENT,
  `medicine` varchar(100) DEFAULT NULL,
  `dosage` varchar(500) DEFAULT NULL,
  `duration` varchar(100) DEFAULT NULL,
  `prescription_id` bigint DEFAULT NULL,
  `date_time` datetime DEFAULT (now()),
  PRIMARY KEY (`med_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1190 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

