DROP TABLE IF EXISTS `doctors`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `doctors` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `speciality` varchar(255) NOT NULL,
  `qualification` varchar(255) NOT NULL,
  `experience` varchar(50) NOT NULL,
  `language` varchar(100) NOT NULL,
  `organisation` varchar(100) NOT NULL,
  `opd_days` varchar(50) NOT NULL,
  `opd_timing` varchar(50) NOT NULL,
  `fees` int NOT NULL,
  `problems` varchar(500) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `specialities` varchar(255) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=105 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

