DROP TABLE IF EXISTS `prescription_test`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `prescription_test` (
  `chief_complaints` varchar(500) NOT NULL,
  `observations` varchar(500) NOT NULL,
  `investigations` varchar(500) NOT NULL,
  `advices` varchar(500) NOT NULL,
  `medicine` varchar(100) NOT NULL,
  `dosage` varchar(100) NOT NULL,
  `duration` varchar(50) NOT NULL,
  `patient_id` varchar(100) NOT NULL,
  `patient_age` int NOT NULL,
  `patient_gender` varchar(10) DEFAULT NULL,
  `dependent_id` varchar(100) DEFAULT NULL,
  `med_id` int NOT NULL AUTO_INCREMENT,
  `prescription_id` bigint DEFAULT NULL,
  `doctor_name` varchar(50) DEFAULT NULL,
  `doctor_id` varchar(100) DEFAULT NULL,
  `qualification` varchar(100) DEFAULT NULL,
  `mci_license_number` varchar(50) DEFAULT NULL,
  `doctor_phone` varchar(20) DEFAULT NULL,
  `date_time` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`med_id`)
) ENGINE=MyISAM AUTO_INCREMENT=1010 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

