DROP TABLE IF EXISTS `student_tickets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student_tickets` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `uhid` varchar(50) NOT NULL,
  `temperature` varchar(10) NOT NULL,
  `spo2` varchar(10) NOT NULL,
  `pr` varchar(10) NOT NULL,
  `bp` varchar(10) NOT NULL,
  `weight` varchar(10) NOT NULL,
  `cc` varchar(1000) NOT NULL,
  `observations` varchar(1000) NOT NULL,
  `medicines` varchar(500) NOT NULL,
  `advices` varchar(1000) NOT NULL,
  `refer_to` varchar(100) NOT NULL,
  `generate_by` varchar(100) NOT NULL,
  `status` varchar(20) DEFAULT 'Scheduled',
  `date_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=4754 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
